/**
 * @event
 * @name scwin.fileTable_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.fileTable_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_noticeAttachFiles');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_noticeAttachFiles'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_DeleteFile (인자 미해석) */
        if (typeof scwin.fileDownload === 'function') { await scwin.fileDownload(r["contnId"], r["contnAttachSeq"]); } else { console.error('[sdd] 행 동작 미정의: scwin.fileDownload (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.fileDownload'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'fileTable.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.img_156_onclick
 * @author Inswave
 * @date 2026. 09. 29
