        ($c.util.getComponent("view_dst2") && $c.util.getComponent("view_dst2").hide ? $c.util.getComponent("view_dst2").hide() : console.warn('[sdd] hide 대상 미해결: ' + "view_dst2"));
        ($c.util.getComponent("view_fil_ods2") && $c.util.getComponent("view_fil_ods2").show ? $c.util.getComponent("view_fil_ods2").show() : console.warn('[sdd] show 대상 미해결: ' + "view_fil_ods2"));
