/**
 * @method
 * @name scwin.selectBox
 * @author Inswave
 * @date 2026. 09. 29
 * @param sysTpCd
 * @returns
 * @hidden N
*/
scwin.selectBox = function (sysTpCd) {
    /* sdd-asis-lifecycle:begin selectBox — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('select[name=corpUsrTpCd]').find('option').remove();
    $('select[name=corpUsrTpCd]').append("<option value=''>전체</option>");
    if (sysTpCd === "1") {
        for (let i = 0; i < (function(){ throw 'unresolved:list:corpUsrTpCdList1'; })(); i++) {
            $('select[name=corpUsrTpCd]').append("<option value='${corpUsrTpCdList1[__i].cdVal}'" + "${(noticeDetail.corpUsrTpCd == entity.cdVal )?'selected':''} " + ">${corpUsrTpCdList1[__i].cdValNm}</option>");
        }
    } else {
        if (sysTpCd === "B") {
            for (let i1 = 0; i1 < (function(){ throw 'unresolved:list:corpUsrTpCdList2'; })(); i1++) {
                $('select[name=corpUsrTpCd]').append("<option value='${corpUsrTpCdList2[__i1].cdVal}'" + "${(noticeDetail.corpUsrTpCd == entity.cdVal )?'selected':''} " + ">${corpUsrTpCdList2[__i1].cdValNm}</option>");
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getStringSize
 * @author Inswave
 * @date 2026. 09. 29
 * @param message
 * @returns
 * @hidden N
*/
scwin.getStringSize = function (message) {
    /* sdd-asis-lifecycle:begin getStringSize — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let i, len = 0;
    for (i = 0; i < message.length; i++) {
        (message.charCodeAt(i) > 255) ? len += 2 : len++;
    }
    return len;
    /* sdd-asis-lifecycle:end */
};


